// Streaming, for real: the built client fetching the development district
// chunk by chunk. The district is generated by `pnpm pack:dev`, which needs
// Blender and KTX-Software; on a machine without them it is not there, and
// these tests skip themselves and say so.

import { expect, test, type Page } from "@playwright/test";
import { STREAM, distanceToChunk, type StreamTier } from "../../packages/world/src/streaming.ts";
import { expectNoSidewaysScroll, watch } from "./harness.ts";

interface PackManifest {
  chunks: { id: string; aabb: number[]; bytes: Record<StreamTier, number> }[];
  sizes: { total: Record<StreamTier, number> };
}

let manifest: PackManifest | null = null;
let manifestBytes = 0;

test.beforeEach(async ({ request }, info) => {
  const response = await request.get("/packs/dev/manifest.json");
  if (!response.ok()) {
    info.annotations.push({ type: "skipped", description: "The development district is not built (pnpm pack:dev needs Blender and KTX-Software). Streaming was not checked here." });
    test.skip();
    return;
  }
  const body = await response.body();
  manifestBytes = body.length;
  manifest = JSON.parse(body.toString()) as PackManifest;
});

/** What a player standing at (x, z) should have downloaded at a tier: the manifest, and every chunk inside the haze. */
function expected(tier: StreamTier, x: number, z: number): { chunks: number; bytes: number } {
  const near = manifest!.chunks.filter((chunk) => distanceToChunk(chunk.aabb, x, z) <= STREAM[tier].farM);
  // Normal and Alta show the reduced model farther out and the full one near: a chunk costs its full tier bytes only when near.
  const bytes = near.reduce((sum, chunk) => sum + (distanceToChunk(chunk.aabb, x, z) <= STREAM[tier].nearM ? chunk.bytes[tier] : chunk.bytes.poupanca), 0);
  return { chunks: near.length, bytes: bytes + manifestBytes };
}

async function settled(page: Page): Promise<{ shown: number; wanted: number; draws: number; triangles: number; bytes: number }> {
  await page.waitForFunction(() => {
    const stream = window.__cena?.stream;
    return stream !== undefined && stream.shown > 0 && stream.loading === 0 && stream.shown === stream.wanted;
  }, undefined, { timeout: 45_000 });
  return page.evaluate(() => ({ shown: window.__cena!.stream!.shown, wanted: window.__cena!.stream!.wanted, draws: window.__cena!.draws, triangles: window.__cena!.triangles, bytes: window.__cena!.sessionBytes! }));
}

test("on the reference phone's tier a player downloads only the chunks inside the haze, and the meter says what it cost", async ({ page }, info) => {
  const seen = watch(page);
  await page.goto("/cena?pack=dev&tier=poupanca&hour=12&at=40,96");
  const here = await settled(page);
  const want = expected("poupanca", 40, 96);
  info.annotations.push({ type: "streaming", description: `at (40, 96) on Poupança: ${here.shown} chunks, ${here.draws} draw calls, ${here.triangles} triangles, ${(here.bytes / 1024).toFixed(0)} KB counted against ${(want.bytes / 1024).toFixed(0)} KB expected; the whole district is ${(manifest!.sizes.total.poupanca / 1024).toFixed(0)} KB` });

  expect(here.shown).toBe(want.chunks);
  // Not the whole district: the far corner is in the haze.
  expect(here.shown).toBeLessThan(manifest!.chunks.length);
  // The meter counts what the network carried: the files' own sizes, with a little for headers.
  expect(here.bytes).toBeGreaterThanOrEqual(want.bytes * 0.9);
  expect(here.bytes).toBeLessThan(want.bytes * 1.1 + 4000);
  // Rule 1, counted from the real scene.
  expect(here.draws).toBeLessThanOrEqual(120);
  expect(here.triangles).toBeLessThanOrEqual(120_000);
  await expect(page.getByRole("status", { name: "Dados usados" })).toContainText("KB nesta sessão");
  await expectNoSidewaysScroll(page);
  expect(seen.errors).toEqual([]);
});

test("walking to the far corner brings its chunks and lets go of the ones left behind", async ({ page }) => {
  await page.goto("/cena?pack=dev&tier=poupanca&hour=12&at=20,20");
  const start = await settled(page);
  expect(start.shown).toBe(expected("poupanca", 20, 20).chunks);

  await page.evaluate(() => window.__cenaGoto!(236, 172));
  await page.waitForFunction((before) => window.__cena!.sessionBytes! > before, start.bytes);
  const far = await settled(page);
  expect(far.shown).toBe(expected("poupanca", 236, 172).chunks);
  // New chunks were paid for; the district was still never downloaded whole.
  expect(far.bytes).toBeGreaterThan(start.bytes);
  expect(far.bytes).toBeLessThan(manifest!.sizes.total.poupanca + 4000);
  // What is drawn is what is near now, not everything ever fetched.
  expect(far.draws).toBeLessThanOrEqual(start.draws + 2);
});

test("a better phone sees farther and in more detail, and pays for it", async ({ browser }) => {
  // Each in a browser that has never been here: what was fetched before is kept by the browser
  // and costs nothing the second time, which the meter rightly counts as nothing.
  const visit = async (tier: string) => {
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto(`/cena?pack=dev&tier=${tier}&hour=12&at=128,96`);
    const result = await settled(page);
    await context.close();
    return result;
  };
  const low = await visit("poupanca");
  const normal = await visit("normal");
  expect(normal.shown).toBeGreaterThanOrEqual(low.shown);
  expect(normal.triangles).toBeGreaterThan(low.triangles);
  expect(normal.bytes).toBeGreaterThan(low.bytes);
  expect(normal.draws).toBeLessThanOrEqual(120);
});

test("a second visit to the same street costs less than the first: what the browser kept is not paid for twice", async ({ page }) => {
  await page.goto("/cena?pack=dev&tier=poupanca&hour=12&at=40,96");
  const first = await settled(page);
  await page.reload();
  const second = await settled(page);
  expect(second.shown).toBe(first.shown);
  expect(second.bytes).toBeLessThanOrEqual(first.bytes);
});
